insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 1, 'How does ROUTE_TEMPLATES ship the limit on each of its route requirements?', '["Set to each licensor''s published figure.", "Set to the EGBEMA study''s limits, which the studio opens with.", "Unset (null): the envelope is the study''s to fill.", "Set on physical law for volume, and left null on composition."]'::jsonb, 2, 'The digest prints ROUTE_TEMPLATES with a limit column that reads null on every requirement: "Every limit ships unset (null): the envelope is the study''s to fill." The studio opens with every limit unset, and every route then reads not fully screened.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 2, 'One requirement appears in the envelope of all four routes in ROUTE_TEMPLATES. Which is it?', '["Minimum volume, in MMscfd.", "Maximum inerts, as a mole fraction.", "Minimum heating value, in Btu/scf.", "Maximum CO2 before treatment, as a mole fraction."]'::jsonb, 0, 'The template table carries a Minimum volume row in MMscfd for cng, mini_lng, lpg_extraction and gas_to_power. The LPG route carries no Maximum inerts row, mini LNG and LPG carry no Minimum heating value, and Maximum CO2 before treatment belongs to mini LNG alone.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 3, 'A template note reads: "CO2 freezes in a liquefaction train and must be removed first. The limit is the licensor''s." Which route and requirement carry it?', '["CNG, on Minimum heating value.", "Gas to power, on Maximum inerts.", "LPG and condensate extraction, on Minimum liquids content.", "Mini LNG, on Maximum CO2 before treatment."]'::jsonb, 3, 'The digest lists the notes the templates carry on two requirements, and this one sits on Mini LNG, Maximum CO2 before treatment. The LPG route''s Minimum liquids content carries the other note, about the liquids paying for the plant. Neither note gives a number.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 4, 'Which requirement carries the template note "Below this the liquids do not pay for the plant, whatever the gas is worth."?', '["Minimum volume, in MMscfd, on the LPG and condensate route.", "Minimum liquids content, in gal/Mscf of C3+, on the LPG route.", "Maximum CO2 before treatment, a mole fraction, on mini LNG.", "Minimum heating value, in Btu/scf, on gas to power or gas to wire."]'::jsonb, 1, 'The digest prints the note on LPG and condensate extraction, Minimum liquids content, whose unit in the template is gal/Mscf of C3+. The mini LNG CO2 requirement carries the other note, and the Minimum volume and heating value rows carry none.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 5, 'screenRoute forms a margin on every checked requirement. How is it formed on a MAXIMUM requirement?', '["The actual minus the limit; a negative margin is a failure.", "The limit minus the actual; a negative margin is a failure.", "The limit minus the actual; a positive margin is a failure.", "The actual over the limit; a ratio above one is a failure."]'::jsonb, 1, 'The digest: "The margin column is the actual minus the limit on a minimum requirement and the limit minus the actual on a maximum; a negative margin is a failure, and the shortfall is its size." The CNG inerts, 0.0460 against a limit of 0.06, print a margin of 0.0140 and a pass.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 6, 'EGBEMA''s mini LNG route checks its CO2 mole fraction of 0.0280 against the study''s Maximum CO2 before treatment of 0.02. Which status and margin does the check table print?', '["pass, with a margin of 0.0140", "fail, with a margin of -2.5000", "unchecked, with a margin of none", "fail, with a margin of -0.0080"]'::jsonb, 3, 'The mini LNG CO2 row prints actual 0.0280, limit 0.02, status fail, margin -0.0080. The 0.0140 is the pass margin on the inerts rows, -2.5000 is mini LNG''s volume margin against its limit of 10, and unchecked with none is the gas to power inerts row.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 7, 'EGBEMA flares 7.5 MMscfd. Against the study''s limits, which route''s Minimum volume check reads fail?', '["Mini LNG, against a limit of 10, margin -2.5000.", "Gas to power, against a limit of 3, margin 4.5000.", "LPG extraction, against 5, margin 2.5000.", "Compressed natural gas, against 5, margin 2.5000."]'::jsonb, 0, 'Every route reads the same actual, 7.5000. Against mini LNG''s limit of 10 the margin is -2.5000 and the status fail. Against 5 on CNG and LPG it is 2.5000 and a pass, and against 3 on gas to power it is 4.5000 and a pass.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 8, 'On gas to power, the study typed minVolumeMMscfd 3 and minGhvBtuScf 950 and nothing else. What does the check table print on that route''s Maximum inerts row?', '["Actual 0.0460, limit 0.06, status pass, margin 0.0140.", "Actual 0.0280, limit unset, status fail, margin -0.0080.", "Actual 0.0460, limit unset, status unchecked, margin none.", "Actual 0.0460, limit unset, status pass, margin none."]'::jsonb, 2, 'The digest prints the gas to power Maximum inerts row as 0.0460, unset, unchecked, none: "A requirement with no limit is reported unchecked; an unset limit is not a satisfied one." The 0.06 limit with a 0.0140 margin is the CNG and mini LNG inerts row, where a limit was typed.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 9, 'Both of gas to power''s checked requirements pass on EGBEMA, with margins of 4.5000 and 298.4110. Which verdict does screenRoute give the route?', '["passes, with Maximum inerts in uncheckedRequirements", "passes, with none in failures and none unchecked", "fails, with Maximum inerts named in failures", "not fully screened, with Maximum inerts in uncheckedRequirements"]'::jsonb, 3, 'The verdict table prints Gas to power or gas to wire: not fully screened, failures none, uncheckedRequirements Maximum inerts. Three verdicts appear: passes, fails and not fully screened, and a requirement with no limit is reported unchecked.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 10, 'Which requirements does the failures field name on EGBEMA''s mini LNG route?', '["Minimum volume and Maximum CO2 before treatment.", "Maximum CO2 before treatment and Maximum inerts.", "Maximum CO2 before treatment, with none other.", "All three: volume, CO2 before treatment, inerts."]'::jsonb, 0, 'The failures field reads: Minimum volume: 7.5000 against 10, short by 2.5000 MMscfd; Maximum CO2 before treatment: 0.0280 against 0.02, short by 0.0080 mole fraction. Mini LNG''s Maximum inerts reads pass at 0.0460 against 0.06, margin 0.0140, so it is not among the failures.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 11, 'How does mini LNG''s failures field print the volume requirement it breaks?', '["7.5000 against a limit of 5, short by 2.5000 MMscfd", "10 against 7.5000, a shortfall of 4.5000 MMscfd", "7.5000 against 10, short by 2.5000 MMscfd", "7.5000 against 10, short by 0.0080 mole fraction"]'::jsonb, 2, 'The digest''s failures entry: "Minimum volume: 7.5000 against 10, short by 2.5000 MMscfd". The limit of 5 is the CNG and LPG volume limit, where 7.5000 passes, 4.5000 is the gas to power volume margin, and 0.0080 mole fraction is the shortfall on the CO2 requirement.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 12, 'The CNG and gas to power routes both check EGBEMA''s heating value of 1248.4110 Btu/scf. Which margins does the check table print?', '["298.4110 on CNG, 248.4110 on gas to power", "248.4110 on CNG and 298.4110 on gas to power", "248.4110 on CNG, with gas to power''s row unchecked", "248.4110 on both, against 1000"]'::jsonb, 1, 'The study typed minGhvBtuScf 1000 on CNG and 950 on gas to power. The table prints margins of 248.4110 and 298.4110, both pass. Gas to power''s unchecked row is Maximum inerts, the requirement it left unset.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 13, 'The Flare Gas to Value Studio opens with every requirement limit unset. Which verdicts does screenRoute give the four EGBEMA routes?', '["not fully screened, on every one of the four", "passes, on all four, as nothing is breached", "fails, on all four, as no requirement is met", "passes on three, with mini LNG left failing"]'::jsonb, 0, 'The digest prints the same four routes with every limit unset, as the studio opens: Compressed natural gas, Mini LNG, LPG and condensate extraction, and Gas to power or gas to wire all read not fully screened. An unset limit is not a satisfied one.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 14, 'screenRoute is asked to screen a gas the analysis refused. What does it answer?', '["Every requirement reads unchecked, and each route reads not fully screened.", "Every requirement reads fail, and mini LNG is listed in screenedOut.", "The routes are screened on the gas as typed, with each status printed.", "It refuses: a characterised gas is required."]'::jsonb, 3, 'The digest''s probe table for screenRoute: a gas the analysis refused gives "REFUSED: A characterised gas is required." No check table and no verdict are printed for it.'),
  ('gasvalue', 'intermediate', 'module', 'm01-four-routes-and-their-envelopes', 15, 'Beside the notes two of its requirements carry, the engine prints one note on ROUTE_TEMPLATES as a whole. Which sentence opens that note?', '["\"The limit is the licensor''s.\" on every row of the table.", "\"Below this the liquids do not pay for the plant.\"", "\"Requirement limits are yours to set.\"", "\"An unset limit is a pass.\""]'::jsonb, 2, 'The engine''s note on the templates opens "Requirement limits are yours to set." The licensor sentence is the note on mini LNG''s CO2 requirement alone, the liquids sentence is the note on the LPG route''s liquids content, and the digest reports a requirement with no limit unchecked.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 1, 'On which basis does yieldCeiling cap the LPG and condensate extraction route?', '["the whole gas mass, as on CNG and LNG", "propane and heavier, capped in t", "the heating value, in MWh per Mscf", "the ethane and heavier, capped in t"]'::jsonb, 1, 'LPG and condensate extraction reads propane and heavier in the ceiling basis column, with a ceiling of 0.0067 t on EGBEMA. No route''s basis is the ethane and heavier, and CNG''s is gas mass.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 2, 'Which two routes does yieldCeiling cap on the same basis, the whole gas mass?', '["mini LNG and LPG, both in tonnes", "CNG and gas to power or gas to wire", "LPG and gas to power or gas to wire", "CNG and mini LNG"]'::jsonb, 3, 'The ceiling basis column reads gas mass for Compressed natural gas and for Mini LNG, propane and heavier for LPG and condensate extraction, and heating value for gas to power. Mini LNG and LPG share a yield unit, t, and differ in basis.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 3, 'How does yieldCeiling turn a heating value into the gas to power ceiling?', '["The heating value times a thousand over BTU_PER_MWH.", "The heating value over BTU_PER_MWH, with no thousand.", "The heating value times BTU_PER_MWH over a thousand.", "The gas mass times the heating value over BTU_PER_MWH."]'::jsonb, 0, 'The digest states the gas to power ceiling as the heating value in MWh: "the heating value times a thousand over BTU_PER_MWH". The heating value is per standard cubic foot and the yield is per Mscf, and BTU_PER_MWH is 3412141.6331.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 4, 'What does yieldCeiling print as the CNG ceiling per Mscf on EGBEMA?', '["25.4954 kg, on the gas mass basis", "18.5 kg, on the gas mass basis", "26.7066 kg, on the gas mass basis", "21.0224 kg, on the gas mass basis"]'::jsonb, 2, 'EGBEMA''s CNG ceiling is 26.7066 kg/Mscf. 21.0224 is OGUTA''s, 25.4954 the studio opening gas''s, and 18.5 is the yield the EGBEMA study typed. Every EGBEMA yield typed sits at or below its ceiling.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 5, 'Read the LPG row of the ceiling table for OGUTA, the lean gas. Which figure is there?', '["0.0010 t", "0.0067 t", "0.0056 t", "0.0210 t"]'::jsonb, 0, 'The LPG row prints 0.0067 on EGBEMA, 0.0010 on OGUTA and 0.0056 on the studio''s opening gas. 0.0210 is OGUTA''s mini LNG ceiling, on the gas mass basis.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 6, 'The studio''s LPG route on its opening gas is typed at 0.0045 t/Mscf. What is printed for that yield?', '["Refused, above the ceiling of 0.0056 t/Mscf it would need.", "Within a ceiling of 0.0067 t/Mscf; typed over ceiling 0.8062.", "Within a ceiling of 0.0056 t/Mscf; typed over ceiling 0.8062.", "Within a ceiling of 0.0255 t/Mscf; typed over ceiling 0.8062."]'::jsonb, 2, 'The digest: "The studio''s LPG route on its opening gas at 0.0045 t/Mscf is within its ceiling of 0.0056 t/Mscf, and the typed yield over the ceiling is 0.8062." 0.0067 is EGBEMA''s LPG ceiling and 0.0255 the studio gas''s mini LNG ceiling.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 7, 'The studio''s opening gas is typed with an LPG yield of 0.02 t/Mscf. Which ceiling and basis does the refusal print?', '["0.0056 t on the propane and heavier basis", "0.005582 t on the gas mass basis", "0.0255 t on the gas mass basis", "0.005582 t on the propane and heavier basis"]'::jsonb, 3, 'The refusal reads: Route "LPG and condensate extraction" yields 0.02 t per Mscf, more than the 0.005582 t the gas holds (propane and heavier). The ceiling table prints the same ceiling to four decimals, 0.0056, and the refusal prints it to six.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 8, 'EGBEMA''s CNG yield is typed at 30 kg/Mscf. What does the engine answer?', '["A year on 30 kg, flagged as above the ceiling of 26.7066 kg.", "REFUSED: more than the 26.706618 kg the gas holds (gas mass).", "A year on 26.7066 kg, the yield cut back to the ceiling.", "REFUSED: more than the 6.6647 kg the gas holds (propane and heavier)."]'::jsonb, 1, 'The digest prints: REFUSED: Route "Compressed natural gas" yields 30 kg per Mscf, more than the 26.706618 kg the gas holds (gas mass). A yield above what the gas contains is refused. No year is printed at 30 kg or at the ceiling.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 9, 'EGBEMA''s gas to power yield is typed at 0 MWh/Mscf, below its ceiling of 0.3659. What does the engine answer?', '["A year with productPerYear of zero and a margin below zero.", "It takes the ceiling of 0.3659 MWh as the yield.", "It takes a zero yield and names it in assumedZero.", "REFUSED: the route needs a positive product yield per Mscf."]'::jsonb, 3, 'The digest: EGBEMA, gas to power at 0 MWh/Mscf gives REFUSED: Route "Gas to power or gas to wire" needs a positive product yield per Mscf. A yield above the ceiling is refused, and a yield of zero is refused.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 10, 'Which function issues the refusal of a yield above what the gas holds?', '["routeEconomics", "yieldCeiling", "screenRoute", "compareRoutes"]'::jsonb, 0, 'The ceiling is yieldCeiling''s, and the refusals are routeEconomics''. yieldCeiling gives the most one Mscf of the gas can make, and routeEconomics refuses a yield above it. screenRoute gives a route passes, fails or not fully screened, and compareRoutes lays the routes side by side.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 11, 'EGBEMA''s gas to power ceiling is 0.3659 MWh per Mscf. Which EGBEMA heating value is that ceiling built on?', '["1537.2878 Btu/scf, the heating values weighted by mass", "1248.4110 Btu/scf, the engine''s heating value on moles", "1308.6069 Btu/scf, the hydrocarbons alone scaled to one", "1035.6050 Btu/scf, the ghvBtuScf of the lean OGUTA gas"]'::jsonb, 1, 'The ceiling is the heating value times a thousand over BTU_PER_MWH, and EGBEMA''s heating value is ghvBtuScf 1248.4110, blended on moles. The digest prints 1537.2878 and 1308.6069 as two shortcuts beside the engine''s figure, and 1035.6050 is OGUTA''s.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 12, 'Mini LNG''s yield unit is the tonne. Which ceiling does its row carry for the associated gas?', '["0.0175 t", "26.7066 t", "0.0267 t", "0.0210 t"]'::jsonb, 2, 'Mini LNG''s yield unit is t, and its EGBEMA ceiling prints 0.0267. 26.7066 is the CNG ceiling in kg, 0.0175 is the mini LNG yield the study typed and 0.0210 is OGUTA''s mini LNG ceiling.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 13, 'Where do the EGBEMA yields the study typed sit against their ceilings?', '["Every one sits at or below its ceiling.", "The LPG yield of 0.0052 t sits above the 0.0010 t ceiling.", "The CNG yield of 18.5 kg sits above the 0.3659 ceiling.", "The mini LNG yield of 0.0175 t sits above its 0.0056 t."]'::jsonb, 0, 'The digest: "Every EGBEMA yield typed sits at or below its ceiling." 0.0010 is OGUTA''s LPG ceiling, 0.3659 is EGBEMA''s gas to power ceiling in MWh, and 0.0056 is the studio gas''s LPG ceiling. EGBEMA''s own ceilings are 26.7066, 0.0267, 0.0067 and 0.3659.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 14, 'Which exported constant does the gas to power ceiling divide by?', '["SCF_PER_LBMOL", "GAL_PER_FT3", "KJ_PER_KWH", "BTU_PER_MWH"]'::jsonb, 3, 'The gas to power ceiling is the heating value times a thousand over BTU_PER_MWH, 3412141.6331 International Table Btu in one megawatt hour. SCF_PER_LBMOL and GAL_PER_FT3 are flareToValue''s mole and gallon constants, and KJ_PER_KWH is lpgCng''s.'),
  ('gasvalue', 'intermediate', 'module', 'm02-what-the-gas-can-yield', 15, 'Which gas prints a gas to power ceiling of 0.3548 MWh per Mscf?', '["EGBEMA, at 1248.4110 Btu/scf", "OGUTA, the lean gas, at 1035.6050 Btu/scf", "The studio''s opening gas, at 1210.7800 Btu/scf", "The studio''s opening gas, at 1248.4110 Btu/scf"]'::jsonb, 2, 'The gas to power row prints 0.3659 on EGBEMA, 0.3035 on OGUTA and 0.3548 on the studio''s opening gas. Each ceiling is built from its own gas''s heating value: ghvBtuScf 1248.4110, 1035.6050 and 1210.7800.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 1, 'EGBEMA''s routes run on 7.5 MMscfd and 355 days. What mscfPerYear does routeEconomics print for each route?', '["2625000.0000 on all four", "2662500.0000 on CNG, and less on the other routes", "2662500000 on all four", "2662500.0000, on every route"]'::jsonb, 3, 'mscfPerYear is the volume in Mscf a day times the on-stream days, and all four rows print 2662500.0000. 2625000.0000 is the CNG route''s figure with the days omitted and the default of 350 taken, and 2662500000 is the flare''s scfPerYear in standard cubic feet.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 2, 'A routeEconomics call on the CNG route carries no on-stream days field at all. Which days and Mscf a year does it use?', '["REFUSED: On-stream days are required, more than 0 and no more than 366.", "It takes onstreamDays 350: mscfPerYear 2625000.0000.", "It takes onstreamDays 355: mscfPerYear 2662500.0000.", "It takes the days as zero and names them in assumedZero."]'::jsonb, 1, 'The digest: "On-stream days OMITTED from routeEconomics take the stated default: onstreamDays 350, mscfPerYear 2625000.0000 on the CNG route." The refusal is what a days box typed blank gets, and 355 is the figure the EGBEMA study typed.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 3, 'EGBEMA''s CNG route is called with its on-stream days typed blank (''''). What does routeEconomics answer?', '["REFUSED: On-stream days are required, more than 0 and no more than 366.", "It takes the stated default, onstreamDays 350, and prints mscfPerYear 2625000.0000.", "It takes the days as zero, names them in assumedZero, and prints a year of none.", "It takes the flare''s 355 days and prints mscfPerYear 2662500.0000 on the route."]'::jsonb, 0, 'routeEconomics prints this refusal for the CNG days box typed blank (''''). The stated default of 350 applies only to days left out of the call, and 355 is EGBEMA''s own typed figure.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 4, 'How does routeEconomics form productPerYear?', '["mscfPerYear times the yield ceiling times the recovery", "mscfPerYear times the yield, with no recovery in it", "mscfPerYear times the yield times the recovery", "mscfPerYear times the yield times the price"]'::jsonb, 2, 'The digest: "productPerYear is that times the yield times the recovery", where that is mscfPerYear. On CNG, 2662500.0000 Mscf, 18.5 kg and 0.88 give 43345500.0000 kg of CNG. Revenue is product times price, and the yield ceiling is no term of the rule.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 5, 'A study clears the recovery box on the CNG route and runs the year. What happens?', '["It takes the recovery as 1 and names it in assumedZero.", "It takes the recovery as zero and prints a product of none.", "It refuses: the route needs a recovery fraction in (0, 1].", "It takes the stated default recovery and prints a full year."]'::jsonb, 2, 'The digest prints "CNG recovery left blank ('''')" with REFUSED: Route "Compressed natural gas" needs a recovery fraction in (0, 1]. A recovery assumed at 100 percent is the quiet optimism that sinks these cases. The recoveries 0 and 1.2 draw the same refusal.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 6, 'How does routeEconomics form a route''s operating cost a year?', '["The fixed cost plus the variable cost per Mscf of the whole parcel.", "The fixed cost plus the variable cost per Mscf recovered.", "The fixed cost plus the variable cost per unit of product.", "The variable cost per Mscf, with the fixed in capital."]'::jsonb, 0, 'The digest: "operating cost is the fixed cost plus the variable cost per Mscf of the whole parcel". On CNG the fixed 1900000 and 0.35 dollars per Mscf print an operating cost of 2831875.00.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 7, 'Which rule gives valuePerMscf, the last figure of a route''s year?', '["The margin over the Mscf the route recovers", "Revenue over mscfPerYear", "Margin over productPerYear", "The margin over mscfPerYear"]'::jsonb, 3, 'The digest: "valuePerMscf is the margin over mscfPerYear." On CNG, a gross margin of 21008150.00 over 2662500.0000 Mscf prints 7.8904.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 8, 'The CNG route''s variable cost box is left blank (''''). Which row does routeEconomics print?', '["operating cost 931875.00, valuePerMscf 8.6040, assumedZero variable operating cost", "operating cost 1900000.00, valuePerMscf 8.2404, assumedZero variable operating cost", "operating cost 2831875.00, valuePerMscf 7.8904, assumedZero none", "REFUSED: the variable operating cost is required"]'::jsonb, 1, 'The digest''s blank cost table: variable cost left blank ('''') gives 1900000.00, 8.2404 and variable operating cost. A cost box left blank is taken as zero and named in assumedZero. 931875.00 and 8.6040 belong to the fixed cost left blank, and 2831875.00 and 7.8904 to both costs typed.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 9, 'The CNG route''s fixed cost is left blank (null). What does assumedZero read, and what operating cost prints?', '["fixed operating cost; 931875.00", "variable operating cost; 1900000.00", "none; 2831875.00, as both are typed", "fixed operating cost; 1900000.00"]'::jsonb, 0, 'The digest''s row for the fixed cost left blank (null) prints operatingCostPerYear 931875.00, valuePerMscf 8.6040 and assumedZero fixed operating cost. 1900000.00 is the operating cost with the variable cost blank.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 10, 'Which row does routeEconomics print for EGBEMA''s LPG and condensate extraction route?', '["revenue 12338557.50, margin 7540432.50, value per Mscf 2.8321", "revenue 5335863.00, margin 3345500.00, value per Mscf 0.7476", "revenue 18232134.38, margin 11301509.38, value per Mscf 4.2447", "revenue 5335863.00, margin 1990363.00, value per Mscf 0.7476"]'::jsonb, 3, 'The LPG row prints revenuePerYear 5335863.00, operatingCostPerYear 3345500.00, grossMarginPerYear 1990363.00 and valuePerMscf 0.7476. 3345500.00 is its operating cost. The 12338557.50 row is gas to power and the 18232134.38 row is mini LNG.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 11, 'EGBEMA''s routes scale their capital with modularRefinery''s power law. Which scalingExponent does each route print?', '["0.6, STICK_BUILT", "0.9 on all four routes", "0.9 on CNG and 0.6 on the other routes", "0.88, the CNG recovery"]'::jsonb, 1, 'The capital table prints scalingExponent 0.9 on all four routes, and modularRefinery exports MODULAR 0.9 and STICK_BUILT 0.6. The six-tenths column is the same scaling at STICK_BUILT, printed beside the engine''s figure.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 12, 'What does the capital table print as mini LNG''s modular minus six-tenths?', '["1899679.94", "-2643920.39", "-9909377.93", "-4959777.43"]'::jsonb, 2, 'Mini LNG prints capitalCost 42870938.50 at 0.9 and 52780316.43 on the six-tenths rule, and the difference column prints -9909377.93. 1899679.94 is CNG''s, -2643920.39 LPG''s and -4959777.43 gas to power''s.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 13, 'A study clears the scaling exponent box on the CNG route. Which exponent and capital follow?', '["STICK_BUILT: 0.6, capitalCost 27438303.12.", "No exponent: a null capital and a note.", "REFUSED: a scaling exponent is required.", "The MODULAR exponent: 0.9, capitalCost 29337983.06."]'::jsonb, 3, 'The digest: "With the scaling exponent typed blank ('''') routeEconomics takes the MODULAR exponent: scalingExponent 0.9, capitalCost 29337983.06 on the CNG route." 27438303.12 is the six-tenths reading on the same plant.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 14, 'A route''s reference plant cost is left blank. What does routeEconomics give for capital?', '["Capital null, with the note \"No capital cost: a reference plant cost and capacity are required to scale from.\"", "Capital zero, named in assumedZero beside the operating costs.", "REFUSED: a reference plant cost is required to scale from.", "Capital scaled from the MODULAR default plant for the route."]'::jsonb, 0, 'The digest: "With the reference cost left blank the capital is null and the note reads: No capital cost: a reference plant cost and capacity are required to scale from." A blank cost box is the one taken as zero in assumedZero, and no default plant is printed.'),
  ('gasvalue', 'intermediate', 'module', 'm03-a-routes-year', 15, 'What cash flow does routeEconomics hand on for EGBEMA''s gas to power route?', '["year0 -32753824.67, recurring 12338557.50", "year0 -42870938.50, recurring 7540432.50", "year0 -32753824.67, recurring 7540432.50", "year0 -29331801.26, recurring 1990363.00"]'::jsonb, 2, 'Year 0 is the capital as a negative and the recurring figure is the margin: gas to power prints -32753824.67 and 7540432.50. 12338557.50 is its revenue. The engine does not discount the flow: "A second discounted cash flow in this module would be a second answer."'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 1, 'The CNG route recovers 0.88 of EGBEMA''s flare of 215946.438 t/yr of CO2e. What avoidedFlareCo2eTonnes does abatement print?', '["190032.865", "215946.438", "218032.865", "202989.652"]'::jsonb, 0, 'The digest: "The gas it does not recover is still flared, so the avoided flare CO2e is the flare''s CO2e times the recovery." CNG prints 190032.865. 215946.438 is the whole flare, 218032.865 the net against diesel and 202989.652 the gas to power route''s avoided flare at 0.94.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 2, 'How does abatement form the net abatement from its three terms?', '["The avoided flare, plus what burning the product emits, less what the product displaces.", "The whole flare, less what burning the product emits, plus what the product displaces.", "The avoided flare, less what burning the product emits, plus what the product displaces.", "What the product displaces, less the avoided flare, less what burning the product emits."]'::jsonb, 2, 'The digest: "The net abatement is the avoided flare, less what burning the product emits, plus what the product displaces." The avoided flare is the flare''s CO2e times the recovery, 190032.865 on the CNG route.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 3, 'Against the counterfactual "CNG displacing diesel in haulage trucks", what does abatement print?', '["net 190032.865; net minus the gross flare -25913.573", "net 218032.865; net minus the gross flare 2086.427", "net 218032.865; and -2010.348 below the flare", "net 62032.865; net minus the gross flare -153913.573"]'::jsonb, 1, 'The diesel row: displaced fuel 156000, net 218032.865, net minus the gross flare 2086.427. The other two CNG rows print nets of 190032.865 and 62032.865, and -2010.348 is no CNG figure.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 4, 'Against "CNG displacing pipeline gas already burned", which net abatement and net minus the gross flare print?', '["218032.865 and 2086.427 t/yr", "62032.865 and -153913.573", "190032.865 and -153913.573", "190032.865 and -25913.573"]'::jsonb, 3, 'On that row the net prints 190032.865 and its difference from the gross flare prints -25913.573. The 218032.865 and 2086.427 pair is the diesel row, and 62032.865 with -153913.573 the row where nothing is displaced.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 5, '"CNG sold into a market that burned nothing" displaces 0. What net abatement does abatement print for it?', '["190032.865 t/yr", "-2010.348 t/yr", "215946.438 t/yr", "62032.865 t/yr"]'::jsonb, 3, 'Its row: displaced fuel 0, net 62032.865, net minus the gross flare -153913.573. -2010.348 belongs to gas to power, and 215946.438 is the flare itself.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 6, 'On the three CNG counterfactuals, which one gives a net abatement LARGER than the gross flare?', '["Displacing pipeline gas already burned", "Displacing diesel in haulage trucks", "A market that burned nothing, as no fuel is burned", "None of the three: a net never exceeds the flare"]'::jsonb, 1, 'The digest: "Displacing diesel, the net abatement is larger than the gross flare; displacing gas already burned, or selling into a market that burned nothing, it is smaller." The diesel row''s net minus the gross flare is 2086.427.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 7, 'Gas to power recovers 0.94, and its counterfactual "Gas to power for a new load that burned nothing" types product combustion 205000 and displaced 0. What does abatement print?', '["avoided 202989.652; net -2010.348; this route adds emissions", "avoided 202989.652; net 218032.865; this route abates", "avoided 190032.865; net 62032.865; this route abates", "avoided 215946.438; net -2010.348; this route adds emissions"]'::jsonb, 0, 'The digest prints avoidedFlareCo2eTonnes 202989.652 and netAbatementTonnesCo2ePerYear -2010.348, and: "The net is below zero: this route adds emissions." 215946.438 is the whole flare, and 190032.865 and 62032.865 are the CNG route''s figures.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 8, 'Across its three counterfactuals, what does the CNG route''s avoidedFlareCo2eTonnes print?', '["62032.865 on each of the three", "215946.438 on each row", "190032.865 on each of the three rows", "190032.865 on diesel only, and null on the other two"]'::jsonb, 2, 'The counterfactual table prints avoidedFlareCo2eTonnes 190032.865 on the diesel, pipeline gas and burned nothing rows alike. 215946.438 is the whole flare, and 62032.865 is the net where nothing is displaced.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 9, 'In abatement''s blocked probe table, which probe prints the blockedBy text that names the methane global warming potential?', '["the probe with no GWP", "the probe at 1.5", "the no label probe", "the probe with no displaced fuel figure"]'::jsonb, 0, 'The digest''s probe "no GWP" prints a net of null beside blockedBy "no methane global warming potential supplied". Recovery 1.5 prints the recovery text, and the label and displaced fuel probes print the counterfactual text.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 10, 'A recovery of 1.5 is typed into abatement. What does blockedBy read?', '["the counterfactual is not declared: what the product displaces, and what burning it emits", "no methane global warming potential supplied", "recovery capped at 1: the whole flare is taken as avoided", "no recovery fraction in (0, 1]: gas the plant does not recover is still flared"]'::jsonb, 3, 'The digest''s probe "recovery 1.5" prints a net of null and blockedBy "no recovery fraction in (0, 1]: gas the plant does not recover is still flared", the same text as the probe with no recovery fraction.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 11, 'Two probes leave out a counterfactual input: one has no counterfactual label, the other no displaced fuel figure. What does blockedBy read?', '["A different text on each probe, naming the missing input", "Nothing on the label probe, as a label is only a name", "The same text on both: the counterfactual is not declared", "The same text on both: no displaced fuel was supplied"]'::jsonb, 2, 'Both probes print a net of null and blockedBy "the counterfactual is not declared: what the product displaces, and what burning it emits".'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 12, 'Beside a blocked net, which figure does abatement still report, and in which field?', '["190032.865 t/yr, as grossClaimIfNoCounterfactual", "215946.438 t/yr, as grossClaimIfNoCounterfactual", "215946.438 t/yr, as netAbatementTonnesCo2ePerYear", "218032.865 t/yr, as grossClaimIfNoCounterfactual"]'::jsonb, 1, 'The digest: "The flare''s gross CO2e is still reported beside a blocked net, as grossClaimIfNoCounterfactual (215946.438 t/yr here): the claim the engine will not make." The net itself prints null on every blocked probe.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 13, 'The warning abatement prints while the counterfactual is undeclared closes on an instruction. Which?', '["\"State the recovery the plant achieves, and the GWP used.\"", "\"Report the gross flare as the abatement until declared.\"", "\"Declare the credit price before the net is reported.\"", "\"State what the product displaces and what burning it emits.\""]'::jsonb, 3, 'That instruction is the warning''s last sentence. Its first sentence reads "No abatement is reported."'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 14, 'With no counterfactual label declared, what does netAbatementTonnesCo2ePerYear print?', '["null", "0", "215946.438", "190032.865"]'::jsonb, 0, 'Every blocked probe prints a net of null. abatement gives no net without every input it rests on, and says which is missing first in blockedBy. The gross flare, 215946.438, is reported in grossClaimIfNoCounterfactual, and 190032.865 is the avoided flare.'),
  ('gasvalue', 'intermediate', 'module', 'm04-the-counterfactual', 15, 'The counterfactual table marks two of its columns as inputs. Which two?', '["recoveryFraction and avoidedFlareCo2eTonnes", "flareCo2eTonnes and the recovery", "product combustion and displaced fuel", "displaced fuel and net minus the gross flare"]'::jsonb, 2, 'The table heads its columns "product combustion (input)" and "displaced fuel (input)". avoidedFlareCo2eTonnes, netAbatementTonnesCo2ePerYear and the net minus the gross flare are printed results.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 1, 'How does creditSensitivity form breakevenCreditPrice?', '["(hurdle minus margin) over the gross flare tonnes", "the lowest typed price that clears", "(hurdle minus margin) over net tonnes", "(hurdle plus margin) over the net tonnes abated"]'::jsonb, 2, 'The field''s own label: breakevenCreditPrice ((hurdle minus margin) over net tonnes), 16.0152 on EGBEMA''s CNG route against diesel. The breakeven is the price at which the route just clears its hurdle, in closed form. The lowest typed price that clears is lowestTestedClearingPrice, a separate field.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 2, 'Credit prices are typed in the order 40, 8, 20, 12. What does lowestTestedClearingPrice read?', '["20", "40", "16.0152", "12"]'::jsonb, 0, 'Of the prices typed, 40 and 20 print clearsHurdle true and 8 and 12 false, and the digest prints lowestTestedClearingPrice 20. 40 is the first price in the order typed that clears, and 16.0152 is the breakeven.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 3, 'Beside the breakeven and lowestTestedClearingPrice, a third price is printed: the first price in the order typed that clears. What does it read, and how does it relate to the other two?', '["20, and it equals the lowest tested price", "16.0152, and it equals the breakeven price", "40, and it is lowestTestedClearingPrice", "40, and it is neither of the other two"]'::jsonb, 3, 'The digest prints the first price in the order typed that clears as 40 and says it "is a third figure again, and it is neither". The breakeven is 16.0152 and lowestTestedClearingPrice is 20.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 4, 'What is printed as the breakeven''s numerator, the hurdle minus the margin, on EGBEMA''s CNG route?', '["24500000 a year", "3491850.00 a year", "8721314.60 a year", "21008150.00 a year"]'::jsonb, 1, 'The digest: "The breakeven''s numerator, the hurdle minus the margin: 3491850.00 a year, over 218032.865 t/yr." 24500000 is the hurdle, 21008150.00 the gross margin and 8721314.60 the credit revenue at a price of 40.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 5, 'At a typed credit price of 12, which row does creditSensitivity print?', '["creditRevenuePerYear 2616394.38, totalMarginPerYear 23624544.38, clearsHurdle false", "creditRevenuePerYear 4360657.30, totalMarginPerYear 25368807.30, clearsHurdle true", "creditRevenuePerYear 2616394.38, totalMarginPerYear 23624544.38, clearsHurdle true", "creditRevenuePerYear 1744262.92, totalMarginPerYear 22752412.92, clearsHurdle false"]'::jsonb, 0, 'The row for 12 prints 2616394.38, 23624544.38 and false: a point clears when its total margin reaches the hurdle of 24500000. The 4360657.30 row is the price of 20 and the 1744262.92 row the price of 8.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 6, 'How does creditSensitivity form creditRevenuePerYear at each typed price?', '["The credit price times the gross flare CO2e in tonnes.", "The credit price times the avoided flare CO2e in tonnes.", "The credit price times the net abatement in tonnes.", "The credit price times the net tonnes, less the margin."]'::jsonb, 2, 'The digest: "creditRevenuePerYear is the credit price times the net abatement in tonnes; totalMarginPerYear is the route''s gross margin plus that". At a price of 20 on 218032.865 t/yr it prints 4360657.30.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 7, 'Against a hurdle of 24500000, what verdict does creditSensitivity give EGBEMA''s CNG route?', '["\"Needs a credit price of 20 per tonne to clear the hurdle. This is a bet on the credit price.\"", "\"Clears the hurdle on its own. Credits are upside; the case stands without them.\"", "\"Needs a credit price of 40 per tonne to clear the hurdle. Credits are upside.\"", "\"Needs a credit price of 16.02 per tonne to clear the hurdle. This is a bet on the credit price.\""]'::jsonb, 3, 'The digest prints standsAloneWithoutCredits false and the verdict "Needs a credit price of 16.02 per tonne to clear the hurdle. This is a bet on the credit price." The field breakevenCreditPrice prints the same price as 16.0152. The stands alone verdict belongs to the hurdle of 20000000.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 8, 'Lower the hurdle margin to 20000000 with the same margin and net. Which two fields follow?', '["standsAloneWithoutCredits true, breakevenCreditPrice 0.0000", "standsAloneWithoutCredits true, breakevenCreditPrice 20", "standsAloneWithoutCredits true, breakevenCreditPrice null", "standsAloneWithoutCredits false, breakevenCreditPrice 0.0000"]'::jsonb, 0, 'The digest: "At a hurdle of 20000000 the route stands alone: standsAloneWithoutCredits true, breakevenCreditPrice 0.0000, verdict Clears the hurdle on its own. Credits are upside; the case stands without them." A null breakeven is what the probes with no margin or no hurdle print, and 20 is lowestTestedClearingPrice at the hurdle of 24500000.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 9, 'creditSensitivity is run on the gas to power counterfactual, whose net abatement is -2010.348 t/yr. What does it answer?', '["REFUSED: No net abatement to sell. Declare the counterfactual first.", "REFUSED: The net abatement is -2010.348 tCO2e a year: the project does not abate, so there are no credits to sell.", "A breakeven of 0.0000, as a negative net needs no credit price.", "No verdict: breakevenCreditPrice null, with the net named."]'::jsonb, 1, 'The digest''s probe table prints that refusal for "the gas-to-power counterfactual, which adds emissions". The "No net abatement to sell" refusal is the one for a counterfactual left undeclared.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 10, 'creditSensitivity is run with the counterfactual undeclared, so there is no net abatement. What does it answer?', '["It prices credits on the gross flare of 215946.438 t/yr.", "It answers with no verdict and a null breakeven.", "REFUSED: The hurdle margin is not a number.", "REFUSED: No net abatement to sell."]'::jsonb, 3, 'The digest: REFUSED: No net abatement to sell. Declare the counterfactual first: a credit computed from a gross flare figure is a credit that cannot be issued. The hurdle refusal is for a hurdle typed as ''x''.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 11, 'The hurdle margin is typed as ''x''. What does creditSensitivity answer?', '["No verdict: breakevenCreditPrice null; \"No hurdle margin, so whether it needs credits cannot be said.\"", "It takes the hurdle as zero, and the route stands alone.", "REFUSED: The hurdle margin is not a number.", "REFUSED: No net abatement to sell."]'::jsonb, 2, 'The digest''s probe "a hurdle that is not a number (''x'')" prints REFUSED: The hurdle margin is not a number. The answer with no verdict and the no hurdle sentence belong to the hurdle left blank ('''').'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 12, 'A study leaves the hurdle box empty (''''). Which answer comes back from the credit test?', '["No verdict: breakevenCreditPrice null, with \"No hurdle margin, so whether it needs credits cannot be said.\"", "REFUSED: The hurdle margin is not a number, as a blank is not a figure.", "standsAloneWithoutCredits true, with the hurdle taken as zero.", "No verdict: breakevenCreditPrice null, with \"Supply its price and costs.\""]'::jsonb, 0, 'The digest''s probe "hurdle left blank ('''')" answers with no verdict: breakevenCreditPrice null; "No hurdle margin, so whether it needs credits cannot be said." The other answer with no verdict belongs to a route whose price is missing.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 13, 'On EGBEMA with the study''s limits, what do compareRoutes'' fields read?', '["bestByValuePerMscf null; leaderNotFullyScreened cng; screenedOut Mini LNG", "bestByValuePerMscf cng; screenedOut Mini LNG; notFullyScreened gas to power", "bestByValuePerMscf cng; screenedOut gas to power; notFullyScreened Mini LNG", "bestByValuePerMscf lpg_extraction; screenedOut Mini LNG; notFullyScreened none"]'::jsonb, 1, 'The digest prints bestByValuePerMscf cng, leaderNotFullyScreened null, screenedOut Mini LNG and notFullyScreened Gas to power or gas to wire. The null best with cng as leader not fully screened is the studio''s opening case, with every limit unset.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 14, 'With every limit unset, as the studio opens, what do bestByValuePerMscf and leaderNotFullyScreened read?', '["cng and null", "cng and cng", "null and null", "null and cng"]'::jsonb, 3, 'The studio''s opening case prints bestByValuePerMscf null and leaderNotFullyScreened cng. With the study''s limits typed, the two read cng and null.'),
  ('gasvalue', 'intermediate', 'module', 'm05-credits-and-the-bid', 15, 'The bid table''s rankingNote opens with one sentence. Which?', '["\"Ranked on net abatement against the counterfactual, which ignores the capital.\"", "\"Ranked on capital, which is handed on undiscounted.\"", "\"Ranked on gross margin per Mscf, which ignores the capital.\"", "\"Ranked on gross margin per Mscf, with the capital netted out of it.\""]'::jsonb, 2, 'The rankingNote reads: "Ranked on gross margin per Mscf, which ignores the capital. Compare that against the capital column before concluding, and value the shortlist in the sanctioned economics engine."'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'What does the validation oracle oracle_flaretovalue.py rebuild from atomic weights?', '["Molar volume", "The molar masses", "Heating values", "The component liquid densities"]'::jsonb, 1, 'In the oracle''s list the atomic weights feed one check: "molar masses rebuilt from atomic weights". The molar volume has its own source.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'From what does the oracle derive the standard molar volume?', '["From SCF_PER_LBMOL", "From the typical liquid densities in the table", "From the atomic weights of each component", "From the gas constant"]'::jsonb, 3, 'The oracle''s list derives the standard molar volume from the gas constant. SCF_PER_LBMOL, 379.49, is a constant the engine exports.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'How does the oracle check the flare by the rule?', '["By mass, cross-checked by the engine''s own flare figure.", "By the rule''s volumetric route alone, with no second route.", "By moles, cross-checked by the rule''s own volumetric route.", "By moles, cross-checked against a measured flare''s figures."]'::jsonb, 2, 'The digest: "the flare by the rule by moles, cross-checked by the rule''s own volumetric route". The oracle checks independently of the engine, and the digest''s preamble says no figure in it is a published analysis or a measured flare.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'The oracle leaves the component heating values and liquid densities unvalidated. What is said of them?', '["They are pinned, and the engine labels them typical.", "They are rebuilt from atomic weights.", "They are derived from the gas constant.", "They are checked by the volumetric route."]'::jsonb, 0, 'The oracle "does not validate the typical heating values and liquid densities: those are pinned, and the engine labels them typical." Atomic weights feed the molar masses, the gas constant the standard molar volume, and the volumetric route cross-checks the flare.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'In what form does the oracle carry the gas?', '["In floating point, in pounds and standard cubic feet", "In exact rationals, in pounds and standard cubic feet", "In the engine''s own figures, to four decimals", "In exact rationals, in kilograms and cubic metres"]'::jsonb, 3, 'The digest: "the gas in exact rationals carried in kilograms and cubic metres". Among the engine''s own constants is SCF_PER_LBMOL, 379.49 standard cubic feet in one lb-mol.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'Which ledgers does the oracle check on a parcel?', '["The route and credit ledgers, leaving comparison", "The route, credit and comparison ledgers", "The carbon inventory and the MAC curve ledgers", "The discounted cash flow and payback ledgers"]'::jsonb, 1, 'The digest lists "the route, credit and comparison ledgers" among the oracle''s checks. The engine assembles its cash flow and hands it on; it does not discount it.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'In the end-to-end reading, the diesel counterfactual takes the avoided flare of 190032.865 t/yr to a net of 218032.865 t/yr. By which two typed figures, and how?', '["Less a product combustion of 128000, plus a displaced fuel of 156000.", "Less a displaced fuel of 156000, plus a product combustion of 128000.", "Less a product combustion of 128000, plus the net minus the gross flare, 2086.427.", "Times the recovery of 0.88, plus a displaced fuel of 156000."]'::jsonb, 0, 'The net abatement is the avoided flare, less what burning the product emits, plus what the product displaces. On the diesel row the product combustion (input) reads 128000 and the displaced fuel (input) 156000. The recovery of 0.88 already sits in the avoided flare, the flare''s CO2e times the recovery, and 2086.427 is the net minus the gross flare, a printed result.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'In the end-to-end table of EGBEMA''s CNG route, what does the step "CNG made, kg/yr" print?', '["2662500.0000", "26.7066", "43345500.0000", "40070.6250"]'::jsonb, 2, 'The step table prints CNG made, kg/yr 43345500.0000. 2662500.0000 is the parcel''s mscfPerYear, 26.7066 the CNG yield ceiling in kg/Mscf and 40070.6250 the mini LNG route''s product in t.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'The end-to-end table prints the CNG route''s capital and its gross margin a year. Which pair?', '["29337983.06 and 21008150.00", "29331801.26 and 21008150.00", "29337983.06 and 23840025.00", "27438303.12 and 21008150.00"]'::jsonb, 0, 'The table prints capital, dollars 29337983.06 and gross margin, dollars a year 21008150.00. 29331801.26 is the LPG route''s capital, 23840025.00 the CNG revenue and 27438303.12 the six-tenths reading on the CNG plant.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'Which step of the end-to-end table sits between the flare CO2e and the net abatement against diesel?', '["the gross claim with no counterfactual, 215946.438 t/yr", "the net against pipeline gas, 190032.865 t/yr", "the avoided flare at the recovery, 202989.652 t/yr", "avoided flare CO2e at the recovery, 190032.865 t/yr"]'::jsonb, 3, 'The table runs flare CO2e 215946.438, then avoided flare CO2e at the recovery 190032.865, then net abatement against diesel 218032.865. 202989.652 is gas to power''s avoided flare, at 0.94, and the net against pipeline gas is no step of this table.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'The end-to-end table closes on the credit. What does its last step print?', '["breakeven credit price, 16.02 dollars per tonne", "breakeven credit price, 16.0152 dollars per tonne", "lowest tested clearing price, 20 dollars per tonne", "the first price that clears, 40 dollars per tonne"]'::jsonb, 1, 'The last step is breakeven credit price, dollars per tonne, 16.0152. The verdict sentence quotes the same price as 16.02, lowestTestedClearingPrice is 20 and the first price in the order typed that clears is 40.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Read the parcel''s value per Mscf step. Which dollar figure is it?', '["8.2404", "4.2447", "7.8904", "8.6040"]'::jsonb, 2, 'The step table prints value per Mscf, dollars 7.8904. 8.2404 and 8.6040 are the CNG route''s values with its variable or its fixed cost left blank, and 4.2447 is mini LNG''s.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'Which figure opens the step-by-step parcel reading, before the product and the capital?', '["CNG yield typed, 18.5 kg/Mscf on the route", "CNG ceiling in the refusal, 26.706618 kg/Mscf", "Minimum volume actual, 7.5000 MMscfd on CNG", "CNG yield ceiling, 26.7066 kg/Mscf"]'::jsonb, 3, 'The first step printed is CNG yield ceiling, kg/Mscf 26.7066. The refusal at 30 kg prints the same ceiling to six decimals, 26.706618, and the yield typed and the volume are inputs and screen figures outside the step table.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The end-to-end table''s net abatement step names one counterfactual. Which, at what figure?', '["diesel, at 218032.865 t/yr", "pipeline gas already burned, at 190032.865 t/yr", "a market that burned nothing, at 62032.865 t/yr", "a new load that burned nothing, at -2010.348 t/yr"]'::jsonb, 0, 'The step reads net abatement against diesel, t/yr, 218032.865, the figure the bid table also carries on CNG. The pipeline gas and burned nothing nets are the CNG route''s other two counterfactuals, and -2010.348 is gas to power''s.'),
  ('gasvalue', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'How is the validation oracle said to check flareToValue''s figures?', '["By re-running the engine on a second machine", "Against measured flares", "Independently of the engine", "Against the typical heating values"]'::jsonb, 2, 'The digest: "What the validation oracle (oracle_flaretovalue.py ...) checks, independently of the engine". Every analysis is invented and illustrative, and the typical heating values are what it does not validate.'),
  ('gasvalue', 'intermediate', 'final', null, 1, 'In ROUTE_TEMPLATES, which yield units do CNG, mini LNG and gas to power carry, in that order?', '["t, t and MWh", "kg, t and MWh", "kg, kg and Btu/scf", "kg, t and Btu/scf"]'::jsonb, 1, 'The template table prints yield unit kg for cng, t for mini_lng and lpg_extraction, and MWh for gas_to_power. Btu/scf is the unit of the Minimum heating value requirement.'),
  ('gasvalue', 'intermediate', 'final', null, 2, 'Mini LNG fails the EGBEMA screen. What does its Maximum inerts row read?', '["status fail, margin -0.0080", "status unchecked, margin none", "status pass, margin 2.5000", "status pass, margin 0.0140"]'::jsonb, 3, 'Mini LNG''s Maximum inerts reads actual 0.0460 against 0.06, status pass, margin 0.0140. Its two failures are the volume and the CO2 before treatment; -0.0080 is the CO2 margin.'),
  ('gasvalue', 'intermediate', 'final', null, 3, 'How does the LPG and condensate extraction route screen on EGBEMA against the study''s limits?', '["passes, with margins of 2.5000 on volume and 1.2205 on liquids", "fails, short by 1.2205 gal/Mscf of C3+ on its liquids", "not fully screened, with Minimum liquids content unchecked", "passes, with margins of 4.5000 on the volume and 1.2205 on the liquids"]'::jsonb, 0, 'The LPG rows print Minimum volume 7.5000 against 5, margin 2.5000, and Minimum liquids content 3.2205 against 2, margin 1.2205, both pass, and the verdict passes. 4.5000 is the gas to power volume margin, against its limit of 3.'),
  ('gasvalue', 'intermediate', 'final', null, 4, 'EGBEMA''s liquids content of 3.2205 gal/Mscf of C3+ is checked against the LPG route''s minGpmC3Plus of 2. Which margin prints, by which rule?', '["0.0140: the limit minus the actual, on a maximum", "2.5000: the actual minus the limit, on a minimum", "1.2205: the actual minus the limit, on a minimum", "1.2205: the limit minus the actual, on a minimum"]'::jsonb, 2, 'The margin is the actual minus the limit on a minimum requirement and the limit minus the actual on a maximum. The liquids row prints 1.2205. 0.0140 is the inerts margin, a maximum, and 2.5000 the LPG volume margin.'),
  ('gasvalue', 'intermediate', 'final', null, 5, 'Which limits did the EGBEMA study type on the Compressed natural gas route?', '["minVolumeMMscfd 3, minGhvBtuScf 950, with the inerts left unset", "minVolumeMMscfd 5, maxInertFraction 0.06, minGhvBtuScf 1000", "minVolumeMMscfd 10, maxCo2Fraction 0.02, maxInertFraction 0.06", "minVolumeMMscfd 5, minGpmC3Plus 2, with no heating value limit"]'::jsonb, 1, 'The digest''s limits table: Compressed natural gas, minVolumeMMscfd 5, maxInertFraction 0.06, minGhvBtuScf 1000. The others are the gas to power, mini LNG and LPG rows.'),
  ('gasvalue', 'intermediate', 'final', null, 6, 'Which three verdicts does screenRoute give a ROUTE?', '["pass, fail and unchecked", "passes, fails and unchecked, as each check reads", "passes, fails and screened out of the comparison", "passes, fails and not fully screened"]'::jsonb, 3, 'The digest: "Three verdicts appear: passes, fails, and not fully screened." pass, fail and unchecked are the statuses of a single requirement''s check, and screenedOut is a compareRoutes field.'),
  ('gasvalue', 'intermediate', 'final', null, 7, 'The associated gas holds propane and heavier. Which LPG ceiling does the table give it?', '["0.0067 t", "0.0052 t", "0.0010 t", "6.6647 t"]'::jsonb, 0, 'The LPG row prints 0.0067 on EGBEMA. 0.0052 t is the LPG yield the study typed, 0.0010 t OGUTA''s ceiling, and 6.6647 is EGBEMA''s c3PlusKgPerMscf, in kg.'),
  ('gasvalue', 'intermediate', 'final', null, 8, 'OGUTA''s CNG ceiling prints 21.0224 kg per Mscf. Which figure characteriseGas prints for OGUTA reads the same?', '["molarMassLbLbmol", "c3PlusKgPerMscf", "kgPerMscf", "ghvBtuScf"]'::jsonb, 2, 'CNG is capped on the whole gas mass, and characteriseGas prints OGUTA''s kgPerMscf as 21.0224. OGUTA''s molarMassLbLbmol is 17.5880, its ghvBtuScf 1035.6050, and its LPG ceiling rests on the propane and heavier.'),
  ('gasvalue', 'intermediate', 'final', null, 9, 'Which typed yield and ceiling are printed for EGBEMA''s gas to power route?', '["0.085 MWh against a ceiling of 0.3548", "0.94 MWh against a ceiling of 0.3659", "0.3659 MWh against a ceiling of 0.3035", "0.085 MWh against a ceiling of 0.3659"]'::jsonb, 3, 'EGBEMA''s gas to power yield typed is 0.085 and its ceiling 0.3659 MWh per Mscf. 0.3548 and 0.3035 are the studio gas''s and OGUTA''s gas to power ceilings, and 0.94 is the route''s recovery.'),
  ('gasvalue', 'intermediate', 'final', null, 10, 'The refusal of a CNG yield of 30 kg/Mscf on EGBEMA names a basis in brackets. Which?', '["(propane and heavier)", "(gas mass)", "(heating value)", "(kg per Mscf of CNG)"]'::jsonb, 1, 'The refusal reads "... more than the 26.706618 kg the gas holds (gas mass)." The LPG refusal on the studio gas names (propane and heavier).'),
  ('gasvalue', 'intermediate', 'final', null, 11, 'The LPG refusal at 0.02 t/Mscf and the CNG refusal at 30 kg/Mscf close on one shared sentence. Which?', '["\"A yield of zero is refused on every route.\"", "\"The ceiling is the licensor''s, and it is yours to set.\"", "\"A yield above what the gas contains is refused.\"", "\"A recovery assumed at 100 percent is the quiet optimism that sinks these cases.\""]'::jsonb, 2, 'The LPG refusal at 0.02 t/Mscf and the CNG refusal at 30 kg/Mscf each close on "A yield above what the gas contains is refused." The recovery sentence closes the recovery refusal.'),
  ('gasvalue', 'intermediate', 'final', null, 12, 'Which CNG ceiling does yieldCeiling print on the studio''s opening gas?', '["25.4954 kg per Mscf", "26.7066 kg per Mscf", "21.0224 kg per Mscf", "0.0255 kg per Mscf"]'::jsonb, 0, 'The studio''s opening gas carries a CNG ceiling of 25.4954 kg on the gas mass basis. The 0.0255 printed for the same gas belongs to mini LNG, in t.'),
  ('gasvalue', 'intermediate', 'final', null, 13, 'Which operating cost a year does routeEconomics print for mini LNG?', '["2831875.00", "3345500.00", "4798125.00", "6930625.00"]'::jsonb, 3, 'The year table prints operatingCostPerYear 6930625.00 on mini LNG, from a fixed 5200000 and 0.65 dollars per Mscf. 2831875.00 is CNG''s, 3345500.00 LPG''s and 4798125.00 gas to power''s.'),
  ('gasvalue', 'intermediate', 'final', null, 14, 'How does grossMarginPerYear relate to the two figures printed before it in the year table?', '["revenuePerYear minus operatingCostPerYear minus the capital", "revenuePerYear minus the variable cost of the recovered gas", "revenuePerYear minus operatingCostPerYear, on every row", "revenuePerYear minus operatingCostPerYear, over mscfPerYear"]'::jsonb, 2, 'The digest: "grossMarginPerYear is revenuePerYear minus operatingCostPerYear, on every row." The margin over mscfPerYear is valuePerMscf, and the capital sits in the cash flow''s year 0.'),
  ('gasvalue', 'intermediate', 'final', null, 15, 'What productPerYear does routeEconomics print for gas to power?', '["212733.7500 MWh", "11352.9000 MWh", "40070.6250 MWh", "43345500.0000 MWh"]'::jsonb, 0, 'Gas to power prints 212733.7500 MWh from 0.085 MWh per Mscf at a recovery of 0.94. 11352.9000 is the LPG route''s product in t, 40070.6250 mini LNG''s in t and 43345500.0000 CNG''s in kg.'),
  ('gasvalue', 'intermediate', 'final', null, 16, 'The recovery refusal carries a second sentence. Which?', '["\"A recovery left blank is taken as zero and named in assumedZero beside the costs.\"", "\"A recovery assumed at 100 percent is the quiet optimism that sinks these cases.\"", "\"Recovery limits are yours to set, and ship unset.\"", "\"Gas the plant does not recover is sold at the price.\""]'::jsonb, 1, 'Every recovery probe, whether typed 0, typed 1.2 or left blank, closes on this sentence after naming the interval (0, 1]. assumedZero is where a blank COST is named.'),
  ('gasvalue', 'intermediate', 'final', null, 17, 'Which route''s capital on the exponent 0.9 comes out ABOVE its six-tenths reading on the same plant?', '["Mini LNG: 42870938.50 against 52780316.43", "LPG and condensate extraction: 29331801.26 against 31975721.65", "Gas to power or gas to wire: 32753824.67 against 37713602.10", "Compressed natural gas: 29337983.06 against 27438303.12"]'::jsonb, 3, 'Only the CNG row prints a positive entry in the modular minus six-tenths column, 1899679.94. The other three rows print negative entries there.'),
  ('gasvalue', 'intermediate', 'final', null, 18, 'What is cashFlow.year0 on every route routeEconomics hands on?', '["The first year''s gross margin, as a positive", "The capitalCost less the recurring margin", "The capitalCost as a negative", "The capitalCost discounted to year 0"]'::jsonb, 2, 'The digest: "Year 0 is the capital as a negative, and the recurring figure is the margin", so CNG''s year0 is -29337983.06 beside a capitalCost of 29337983.06. The engine assembles the cash flow and hands it on; it does not discount it.'),
  ('gasvalue', 'intermediate', 'final', null, 19, 'What does flareToValue''s valuation note say a discounted cash flow in the module would be?', '["\"a second answer\"", "the sanctioned figure", "the ranking basis", "a bet on the price"]'::jsonb, 0, 'The note: "Capital, operating cost and revenue are assembled here and handed to the sanctioned economics engine. A second discounted cash flow in this module would be a second answer." "This is a bet on the credit price" is creditSensitivity''s verdict, and the bid ranks on gross margin per Mscf.'),
  ('gasvalue', 'intermediate', 'final', null, 20, 'From which reference plant is EGBEMA''s CNG capital scaled?', '["80000000 dollars at 15 MMscfd", "24000000 dollars at 6 MMscfd", "38000000 dollars at 10 MMscfd", "50000000 dollars at 12 MMscfd"]'::jsonb, 1, 'The inputs table prints CNG''s reference capital 24000000 at a reference capacity of 6 MMscfd, scaled TO the parcel''s 7.5 MMscfd. The others are the mini LNG, LPG and gas to power plants.'),
  ('gasvalue', 'intermediate', 'final', null, 21, 'Which recovery did the EGBEMA study type on the LPG route, and what product a year does it print?', '["0.86, and 11352.9000 t of LPG", "0.82, and 40070.6250 t of LPG", "0.88, and 43345500.0000 t of LPG", "0.82, and 11352.9000 t of LPG"]'::jsonb, 3, 'The LPG inputs print a yield of 0.0052 t and a recovery of 0.82, and productPerYear 11352.9000 t LPG. 0.86 is mini LNG''s recovery and 40070.6250 its product in t LNG; 0.88 is CNG''s.'),
  ('gasvalue', 'intermediate', 'final', null, 22, 'Only the recovered share of the flare is counted as avoided. Which reason is printed for that rule?', '["The unrecovered gas is vented, all of it methane.", "The GWP applies only to the recovered share.", "What the plant leaves unrecovered is still flared.", "The credit price is set on the recovered share."]'::jsonb, 2, 'The rule reads: "The gas it does not recover is still flared, so the avoided flare CO2e is the flare''s CO2e times the recovery." blockedBy words the same rule: gas the plant does not recover is still flared. An unlit flare, whose gas is vented, is not modelled, and credits are priced on the net abatement.'),
  ('gasvalue', 'intermediate', 'final', null, 23, 'On which CNG counterfactual does the net abatement print the same figure as the avoided flare?', '["Pipeline gas already burned, where displaced fuel and product combustion both read 128000", "Diesel in haulage trucks, where the displaced fuel reads 156000 and the net reads 218032.865", "A market that burned nothing, where the displaced fuel reads 0 and the net reads 62032.865", "None: the net always differs from the avoided flare of 190032.865 on every row"]'::jsonb, 0, 'The pipeline gas row prints product combustion 128000, displaced fuel 128000 and a net of 190032.865, the avoided flare''s figure. The diesel and burned nothing rows print nets of 218032.865 and 62032.865.'),
  ('gasvalue', 'intermediate', 'final', null, 24, 'Which ''net minus the gross flare'' figure belongs to the row whose displaced fuel is 0?', '["-25913.573", "2086.427", "-2010.348", "-153913.573"]'::jsonb, 3, 'The displaced fuel 0 row prints -153913.573 in that column, the pipeline gas row -25913.573 and the diesel row 2086.427. -2010.348 is a net, on gas to power.'),
  ('gasvalue', 'intermediate', 'final', null, 25, 'Which recovery gives gas to power its avoided flare of 202989.652 t/yr?', '["0.88", "0.94", "0.82", "0.86"]'::jsonb, 1, 'The digest: "Gas to power recovers 0.94." avoidedFlareCo2eTonnes 202989.652. 0.88 is CNG''s recovery, 0.82 LPG''s and 0.86 mini LNG''s.'),
  ('gasvalue', 'intermediate', 'final', null, 26, 'abatement''s warning, printed while the counterfactual is undeclared, says which way the abatement moves against the flare''s gross emission. What does it print?', '["Smaller if the product displaces a dirtier fuel; larger if it displaces nothing.", "Larger if the product displaces a dirtier fuel; equal if it displaces nothing.", "Larger if the product displaces a dirtier fuel; smaller if it displaces nothing.", "Equal to the gross emission, whatever the product displaces."]'::jsonb, 2, 'The warning: "recover the gas and somebody burns it, and if that displaces a dirtier fuel the abatement is larger while if it displaces nothing it is smaller." It opens "No abatement is reported."'),
  ('gasvalue', 'intermediate', 'final', null, 27, 'Two abatement probes print blockedBy "no recovery fraction in (0, 1]: gas the plant does not recover is still flared". Which two?', '["no recovery fraction, and recovery 1.5", "no GWP, and recovery 1.5", "no recovery fraction, and no displaced fuel figure", "no counterfactual label, and recovery 1.5"]'::jsonb, 0, 'The blocked probe table prints that text for no recovery fraction and for recovery 1.5. No GWP prints its own text, and the label and displaced fuel probes print the counterfactual text.'),
  ('gasvalue', 'intermediate', 'final', null, 28, 'Which counterfactual label does the gas to power route carry on EGBEMA?', '["\"CNG sold into a market that burned nothing\"", "\"Gas to power displacing diesel generators\"", "\"Gas to power displacing pipeline gas\"", "\"Gas to power for a new load that burned nothing\""]'::jsonb, 3, 'The digest: Gas to power''s counterfactual, "Gas to power for a new load that burned nothing": product combustion 205000, displaced 0. The CNG label is the CNG route''s third counterfactual.'),
  ('gasvalue', 'intermediate', 'final', null, 29, 'The study''s first typed price is 40 dollars per tonne. Which credit revenue, total margin and outcome follow?', '["credit revenue 4360657.30, total margin 25368807.30, clears", "credit revenue 8721314.60, total margin 29729464.60, clears", "credit revenue 8721314.60, total margin 29729464.60, fails", "credit revenue 1744262.92, total margin 22752412.92, fails"]'::jsonb, 1, 'The 40 row prints creditRevenuePerYear 8721314.60, totalMarginPerYear 29729464.60 and clearsHurdle true. The 4360657.30 row is 20 and the 1744262.92 row is 8.'),
  ('gasvalue', 'intermediate', 'final', null, 30, 'How does creditSensitivity decide whether a typed price clears?', '["Its credit revenue alone reaches the hurdle margin the study typed.", "Its price reaches the lowest tested price in the order typed.", "Its total margin, the gross margin plus the credit revenue, reaches the hurdle.", "Its total margin, less the capital, reaches the hurdle margin."]'::jsonb, 2, 'The digest: "totalMarginPerYear is the route''s gross margin plus that; a point clears when its total margin reaches the hurdle." The capital is no term of the credit test.'),
  ('gasvalue', 'intermediate', 'final', null, 31, 'Of the credit prices typed on EGBEMA''s CNG route, which print clearsHurdle true?', '["40 and 20", "40 and 12", "20 and 12", "40, 20 and 12"]'::jsonb, 0, 'The price table prints true at 40 and 20 and false at 8 and 12, with total margins of 22752412.92 and 23624544.38 below the hurdle of 24500000.'),
  ('gasvalue', 'intermediate', 'final', null, 32, 'creditSensitivity is run on a route with its price missing, so it has no margin. What does it answer?', '["REFUSED: The hurdle margin is not a number.", "A breakeven worked on a margin of zero, with the price named in assumedZero.", "No verdict and a null breakeven; it reports that no hurdle margin was given.", "No verdict and a null breakeven; it asks the study to supply its price and costs."]'::jsonb, 3, 'With the price missing there is no margin. The digest prints the answer as having no verdict, a null breakevenCreditPrice and a request to supply the price and costs. A hurdle typed as ''x'' is the refused probe.'),
  ('gasvalue', 'intermediate', 'final', null, 33, 'What does the bid table print in the net abatement column for its four EGBEMA routes?', '["218032.865 on CNG, and -2010.348 on gas to power", "218032.865 on CNG, and none declared on the other three", "215946.438 on each route, the flare''s gross CO2e", "none declared on all four, as credits come later"]'::jsonb, 1, 'The bid table prints netAbatementTonnesCo2ePerYear 218032.865 on Compressed natural gas and none declared on Mini LNG, LPG and gas to power. -2010.348 is a counterfactual probe, and the gross flare is reported as grossClaimIfNoCounterfactual beside a blocked net.'),
  ('gasvalue', 'intermediate', 'final', null, 34, 'What happens to the failing mini LNG route when compareRoutes lays out the bid?', '["It drops the row and names the route in screenedOut.", "It keeps its row and names it in notFullyScreened.", "It keeps its row, verdict fails, and names it in screenedOut.", "It keeps its row and ranks it best on its capital."]'::jsonb, 2, 'The digest: "A route that fails screening stays in the table with its failure named." Mini LNG keeps capital 42870938.50 and value per Mscf 4.2447 beside its verdict, and screenedOut reads Mini LNG. notFullyScreened names gas to power.'),
  ('gasvalue', 'intermediate', 'final', null, 35, 'The rankingNote''s second sentence tells the reader what to do. What?', '["Rank the routes again on net abatement, and price the credits in the sanctioned economics engine.", "Set the limits before relying on the ranking, and screen the routes again.", "Discount each route''s cash flow here, and rank the routes on the result.", "Compare against the capital column, and value the shortlist in the sanctioned economics engine."]'::jsonb, 3, 'After its ranking basis, the note sends the reader to the capital column before concluding and sends the shortlist to the sanctioned economics engine for its value. Setting the limits first is the advice printed while every limit is unset.'),
  ('gasvalue', 'intermediate', 'final', null, 36, 'With every limit unset, as the studio opens, which rankingNote does compareRoutes print?', '["\"No route passes screening yet, so none is ranked best.\" with CNG named as leading on value", "\"Ranked on gross margin per Mscf, which ignores the capital.\" with cng named best", "\"No route passes screening yet, so none is ranked best.\" with cng named bestByValuePerMscf", "\"Ranked on net abatement, which ignores the capital.\" with Compressed natural gas named as the leader"]'::jsonb, 0, 'The opening note reads: "No route passes screening yet, so none is ranked best. Compressed natural gas leads on value among routes not fully screened; set the limits before relying on it." bestByValuePerMscf reads null and leaderNotFullyScreened reads cng. The note on gross margin per Mscf is the one printed with the study''s limits typed.'),
  ('gasvalue', 'intermediate', 'final', null, 37, 'Where do the credit prices creditSensitivity tests come from?', '["The engine''s table of market credit prices.", "The case types them; the engine ships none.", "The engine''s default list, 40, 8, 20 and 12.", "The hurdle margin over the net abatement."]'::jsonb, 1, 'The digest: "Credit prices are case inputs; the engine ships none." 40, 8, 20 and 12 are the prices the EGBEMA case typed. The hurdle minus the margin over the net tonnes is the breakeven.'),
  ('gasvalue', 'intermediate', 'final', null, 38, 'The breakeven''s numerator, the hurdle minus the margin, is 3491850.00 a year. Over which figure does creditSensitivity divide it?', '["215946.438 t/yr, the flare''s gross CO2e", "190032.865 t/yr, the avoided flare CO2e", "218032.865 t/yr, the net abatement against diesel", "21008150.00 a year, the route''s gross margin"]'::jsonb, 2, 'The field''s label reads breakevenCreditPrice ((hurdle minus margin) over net tonnes), and the numerator is printed as 3491850.00 a year, over 218032.865 t/yr. A credit computed from a gross flare figure is a credit that cannot be issued, and the avoided flare is only the first term of the net.'),
  ('gasvalue', 'intermediate', 'final', null, 39, 'abatement multiplies the flare''s CO2e by one figure the CNG route also types for its year. Which?', '["The yield, 18.5 kg per Mscf", "The price, 0.55 dollars a kg", "The variable cost, 0.35 per Mscf", "The recovery, 0.88"]'::jsonb, 3, 'The avoided flare CO2e is the flare''s CO2e times the recovery, 0.88 on CNG, and productPerYear is mscfPerYear times the yield times the same recovery.'),
  ('gasvalue', 'intermediate', 'final', null, 40, 'Which row does the bid table print for gas to power or gas to wire?', '["not fully screened, capital 32753824.67, value per Mscf 2.8321", "passes, capital 32753824.67, value per Mscf 2.8321", "not fully screened, capital 37713602.10, value per Mscf 2.8321", "not fully screened, capital 32753824.67, value per Mscf 0.7476"]'::jsonb, 0, 'The bid row prints not fully screened, capitalCost 32753824.67, grossMarginPerYear 7540432.50 and valuePerMscf 2.8321. 37713602.10 is the six-tenths reading on its plant and 0.7476 is the LPG route''s value.'),
  ('gasvalue', 'intermediate', 'final', null, 41, 'A study leaves several boxes blank. Which blank does the engine refuse outright?', '["A variable cost box on a route", "The recovery on a route", "The reference plant cost", "The hurdle margin in the credit test"]'::jsonb, 1, 'A blank recovery draws REFUSED: needs a recovery fraction in (0, 1]. A blank cost is taken as zero and named in assumedZero, a blank reference cost gives a null capital with a note, and a blank hurdle is answered with no verdict.'),
  ('gasvalue', 'intermediate', 'final', null, 42, 'Which blank box does routeEconomics fill from a stated value, and print the value it took?', '["The recovery, which takes 1 and prints it", "The on-stream days, which take the default 350", "The scaling exponent, which takes MODULAR 0.9", "The hurdle margin, which takes zero"]'::jsonb, 2, 'With the scaling exponent typed blank, routeEconomics takes the MODULAR exponent: scalingExponent 0.9. A blank recovery and blank on-stream days are refused; 350 is the default for days OMITTED from the call. A blank hurdle is creditSensitivity''s, answered with no verdict.');
